@page "/settings"
@namespace sv_ba6e2086d0df4c599bdb26d54815ba69.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="s => _activeSection = s" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
}

/* ── Settings Layout ── */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 100px);
    gap: 0;
}

/* ── Sidebar ── */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.25rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
}

.settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.625rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: background-color 0.15s, border-color 0.15s;
}

.settings-sidebar .nav-link:hover {
    background: #e9ecef;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* ── Content Area ── */
.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    max-width: 900px;
}

.settings-section h4 {
    margin-bottom: 0.25rem;
}

/* ── Avatar Preview ── */
.avatar-preview {
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    border: 1px solid #dee2e6;
}

.avatar-preview img {
    object-fit: cover;
}

/* ── Appearance Preview ── */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

.preview-footer {
    padding: 0.5rem 1rem;
    border-top: 1px solid #dee2e6;
}

.preview-button {
    padding: 0.375rem 0.75rem;
    border-radius: 0.25rem;
    border: 1px solid #0d6efd;
    background: #0d6efd;
    color: #fff;
    cursor: pointer;
}

/* Light theme (default) */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f8f9fa;
}

.preview-light .preview-footer {
    background: #f8f9fa;
}

/* Dark theme */
.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .preview-header {
    background: #181825;
    border-color: #45475a;
}

.preview-dark .preview-footer {
    background: #181825;
    border-color: #45475a;
}

.preview-dark .preview-button {
    background: #89b4fa;
    border-color: #89b4fa;
    color: #1e1e2e;
}

/* System theme */
.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

/* Font sizes */
.preview-font-sm { font-size: 0.825rem; }
.preview-font-md { font-size: 1rem; }
.preview-font-lg { font-size: 1.15rem; }

/* Compact mode */
.preview-compact .preview-header { padding: 0.375rem 0.75rem; }
.preview-compact .preview-body { padding: 0.5rem 0.75rem; }
.preview-compact .preview-body p { margin-bottom: 0.25rem; }
.preview-compact .preview-footer { padding: 0.25rem 0.75rem; }

/* ── Modal backdrop fix ── */
.modal-backdrop.show {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1040;
}

.modal.d-block {
    position: fixed;
    inset: 0;
    z-index: 1050;
    display: flex !important;
    align-items: center;
    justify-content: center;
}

